import{_ as a,C as r,o as s,c as n,a3 as i,E as l,w as d,j as t}from"./chunks/framework.CtBtfbN4.js";const u="/versions/v0.16.28/screens/macros/macro_poly_aftertouch.png",_=JSON.parse('{"title":"Poly Aftertouch","description":"","frontmatter":{"title":"Poly Aftertouch","pageClass":"macro-doc"},"headers":[],"relativePath":"macros/poly-aftertouch.md","filePath":"macros/poly-aftertouch.md"}'),c={name:"macros/poly-aftertouch.md"};function h(p,e,m,g,f,b){const o=r("ManualRelated");return s(),n("div",null,[e[1]||(e[1]=i('<h1 id="poly-aftertouch" tabindex="-1">Poly Aftertouch <a class="header-anchor" href="#poly-aftertouch" aria-label="Permalink to &quot;Poly Aftertouch&quot;">​</a></h1><p><strong>Firmware menu name:</strong> POLY AT</p><p>Send polyphonic aftertouch (per-note pressure).</p><p><img src="'+u+'" alt="Poly Aftertouch macro" class="screen"></p><h2 id="when-to-use-it" tabindex="-1">When to use it <a class="header-anchor" href="#when-to-use-it" aria-label="Permalink to &quot;When to use it&quot;">​</a></h2><p>Use <strong>POLY AT</strong> (polyphonic aftertouch) when the destination expects per-note pressure (<code>0xA0</code>). Set <strong>Note</strong> to the MIDI note (shown as a name using Middle C), then min/max for the 0–127 pressure range.</p><h2 id="parameters" tabindex="-1">Parameters <a class="header-anchor" href="#parameters" aria-label="Permalink to &quot;Parameters&quot;">​</a></h2><div class="device-params-table"><table tabindex="0"><thead><tr><th>Parameter</th><th>Range</th><th>What it does</th></tr></thead><tbody><tr><td>Mode</td><td>—</td><td>Macro output type. Change this to switch between MIDI, internal routing, and CV16 targets.</td></tr><tr><td>Note</td><td>Note name</td><td>MIDI note that receives polyphonic aftertouch pressure. Shown as a note name using <strong>Settings → MIDI Settings → Middle C</strong> (default: MIDI 60 = C3). Encoder still steps MIDI 0–127. The knob maps pressure 0–127 on this note.</td></tr><tr><td>Minimum</td><td>Mode-specific</td><td>Value sent when the knob is at minimum travel. Units follow the target (MIDI 0–127, 14-bit 0–16383, device parameter native range, CV volts, LFO %, etc.).</td></tr><tr><td>Maximum</td><td>Mode-specific</td><td>Value sent when the knob is at maximum travel. Must be greater than or equal to <strong>Minimum</strong>.</td></tr><tr><td>Channel</td><td>Global, 1 – 16</td><td>MIDI channel for outgoing messages. <strong>Global</strong> uses the project&#39;s global channel setting.</td></tr><tr><td>Invert</td><td>True / False</td><td>When <strong>True</strong>, knob clockwise motion maps to decreasing values (minimum ↔ maximum swapped).</td></tr><tr><td>Outputs</td><td>USB / DIN / combos</td><td>Which physical MIDI outputs carry this macro: USB, <strong>Out 1</strong>, <strong>Out 2</strong>, or combined masks.</td></tr></tbody></table></div><h2 id="midi-outputs" tabindex="-1">MIDI outputs <a class="header-anchor" href="#midi-outputs" aria-label="Permalink to &quot;MIDI outputs&quot;">​</a></h2><p>The <strong>Outputs</strong> field selects one of these port combinations:</p><ul><li>None</li><li>USB</li><li>Out 1</li><li>USB + Out 1</li><li>Out 2</li><li>USB + Out 2</li><li>Out 1 + Out 2</li><li>USB + Out 1 + Out 2</li></ul>',11)),l(o,{title:"Related topics"},{default:d(()=>[...e[0]||(e[0]=[t("ul",null,[t("li",null,[t("a",{href:"/versions/v0.16.28/macros/"},"Macros overview")]),t("li",null,[t("a",{href:"/versions/v0.16.28/macros/setting-up-macros"},"Setting up macros")]),t("li",null,[t("a",{href:"/versions/v0.16.28/concepts/modulation"},"Modulation")])],-1)])]),_:1})])}const M=a(c,[["render",h]]);export{_ as __pageData,M as default};
